import{c as e,Q as l,j as i,m as s}from"./chunks/framework.DOi4mjdC.js";const a="/assets/%E6%88%90%E9%95%BF%E5%9C%B0%E5%9B%BE-9.DqJPuuK5.png",_=JSON.parse('{"title":"编程接口概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"编程接口概述","slug":"编程接口概述"}],"relativePath":"guide/编程指南/类库API/编程接口概述.md","filePath":"guide/编程指南/类库API/编程接口概述.md"}'),c={name:"guide/编程指南/类库API/编程接口概述.md"};function n(o,t,r,A,p,I){return l(),i("div",null,[...t[0]||(t[0]=[s('<h1 id="编程接口概述" tabindex="-1">编程接口概述 <a class="header-anchor" href="#编程接口概述" aria-label="Permalink to &quot;编程接口概述&quot;">​</a></h1><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>本章提供编程API的概述。具体API参考见<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/README.md" target="_blank" rel="noreferrer">Ascend C API</a>。</p></div><p>Ascend C提供一组类库API，开发者使用标准C++语法和类库API进行编程。Ascend C编程类库API示意图如下所示，分为：</p><ul><li><p><strong>语言扩展层 C API</strong>：开放芯片完备编程能力，支持数组分配内存，一般基于指针编程，提供与业界一致的C语言编程体验。</p></li><li><p><strong>基础API</strong>：实现对硬件能力的抽象，开放芯片的能力，保证完备性和兼容性。标注为ISASI（Instruction Set Architecture Special Interface，硬件体系结构相关的接口）类别的API，不能保证跨硬件版本兼容。</p></li><li><p><strong>高阶API</strong>：实现一些常用的计算算法，用于提高编程开发效率，通常会调用多种基础API实现。高阶API包括数学库、Matmul、Softmax等API。高阶API可以保证兼容性。</p></li><li><p><strong>Utils API（公共辅助函数）</strong>：丰富的通用工具类，涵盖标准库、平台信息获取、运行时编译及日志输出等功能，支持开发者高效实现算子开发与性能优化。</p></li></ul><p><img src="'+a+'" alt=""></p><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>Ascend C API所在头文件目录为：</p><ul><li>基础API：${INSTALL_DIR}/include/ascendc/basic_api/interface</li><li>高阶API：（注意，如下目录头文件中包含的接口如果未在资料中声明，属于间接调用接口，开发者无需关注） <ul><li>${INSTALL_DIR}/include/ascendc/highlevel_api/lib</li><li>${INSTALL_DIR}/include/tiling ${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。 使用Ascend C API依赖的库文件说明如下：</li></ul></li><li>基础API：不涉及</li><li>高阶API：因高阶API配套Host Tiling接口，需要链接libtiling_api.a。</li></ul></div>',6)])])}const u=e(c,[["render",n]]);export{_ as __pageData,u as default};
